package com.personal.assistant.module.system.service;import com.personal.assistant.module.system.dto.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.quartz.Scheduler;import org.springframework.test.util.ReflectionTestUtils;import javax.sql.DataSource;import java.sql.Connection;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class SystemServiceTest{@Mock DataSource dataSource;@Mock Scheduler scheduler;@Mock Connection connection;SystemService service;@BeforeEach void setUp(){service=new SystemService(dataSource,scheduler);ReflectionTestUtils.setField(service,"appName","test-app");ReflectionTestUtils.setField(service,"storagePath",".");ReflectionTestUtils.setField(service,"warningPercent",100d);}@Test void statusReportsDatabaseSchedulerAndStorage()throws Exception{when(dataSource.getConnection()).thenReturn(connection);when(connection.isValid(2)).thenReturn(true);when(scheduler.isStarted()).thenReturn(true);when(scheduler.isShutdown()).thenReturn(false);SystemStatus s=service.status();assertEquals("UP",s.database());assertEquals("UP",s.scheduler());assertEquals("OK",s.storage().status());assertTrue(s.storage().totalBytes()>0);}@Test void healthIsDownWhenDatabaseFails()throws Exception{when(dataSource.getConnection()).thenThrow(new java.sql.SQLException("offline"));assertEquals("DOWN",service.checkHealth().status());}}